import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ storage: multer.memoryStorage() });
const router = express.Router();

interface MatchResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
}

function analyzeResumeText(resumeText: string, jobKeywords: string[]): MatchResult {
  const lowerResume = resumeText.toLowerCase();
  const matched: string[] = [];
  const missing: string[] = [];

  jobKeywords.forEach((kw) => {
    if (lowerResume.includes(kw.toLowerCase())) {
      matched.push(kw);
    } else {
      missing.push(kw);
    }
  });

  const score = jobKeywords.length > 0 ? Math.round((matched.length / jobKeywords.length) * 100) : 0;

  return {
    matchScore: score,
    matchedKeywords: matched,
    missingKeywords: missing,
  };
}

router.post('/api/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF resume file provided.' });
      return;
    }

    const { jobDescription, keywords } = req.body;
    if (!jobDescription || !keywords) {
      res.status(400).json({ error: 'Job description and keywords array required.' });
      return;
    }

    const parsedPdf = await pdfParse(req.file.buffer);
    const keywordList: string[] = typeof keywords === 'string' ? JSON.parse(keywords) : keywords;

    const analysis = analyzeResumeText(parsedPdf.text, keywordList);

    res.status(200).json({
      success: true,
      fileName: req.file.originalname,
      pageCount: parsedPdf.numpages,
      ...analysis,
    });
  } catch (error) {
    console.error('Error processing resume scan:', error);
    res.status(500).json({ error: 'Internal server error during PDF parsing.' });
  }
});

export default router;

import React, { useState, ChangeEvent, FormEvent } from 'react';

interface ScanResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  fileName: string;
}

export const TailwindMatchDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDescription, setJobDescription] = useState<string>('');
  const [keywordsInput, setKeywordsInput] = useState<string>('React, TypeScript, Node.js, Tailwind, GraphQL');
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ScanResult | null>(null);

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!file) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);
    formData.append(
      'keywords',
      JSON.stringify(keywordsInput.split(',').map((k) => k.trim()).filter(Boolean))
    );

    try {
      const response = await fetch('/api/scan', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      if (data.success) {
        setResult(data);
      }
    } catch (err) {
      console.error('Scan request failed:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-50 min-h-screen text-slate-800">
      <header className="mb-8 text-center">
        <h1 className="text-3xl font-extrabold tracking-tight text-slate-900">AI Resume Keyword Scanner</h1>
        <p className="text-sm text-slate-500 mt-2">Optimize your resume against target job descriptions instantly.</p>
      </header>

      <form onSubmit={handleSubmit} className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 grid grid-cols-1 gap-6 mb-8">
        <div>
          <label className="block text-sm font-semibold mb-2">Upload PDF Resume</label>
          <input type="file" accept=".pdf" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100" />
        </div>
        <div>
          <label className="block text-sm font-semibold mb-2">Job Description</label>
          <textarea rows={4} value={jobDescription} onChange={(e) => setJobDescription(e.target.value)} placeholder="Paste target job description here..." className="w-full p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm" />
        </div>
        <div>
          <label className="block text-sm font-semibold mb-2">Target Keywords (Comma Separated)</label>
          <input type="text" value={keywordsInput} onChange={(e) => setKeywordsInput(e.target.value)} className="w-full p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm" />
        </div>
        <button type="submit" disabled={loading || !file} className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white font-semibold rounded-lg transition duration-200">
          {loading ? 'Analyzing Resume...' : 'Calculate Match Score'}
        </button>
      </form>

      {result && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 grid grid-cols-1 md:grid-cols-3 gap-6 items-center">
          <div className="flex flex-col items-center justify-center p-6 bg-blue-50 rounded-xl border border-blue-100">
            <div className="text-5xl font-black text-blue-600 mb-2">{result.matchScore}%</div>
            <div className="text-xs font-bold uppercase tracking-wider text-blue-500">Match Score</div>
          </div>
          <div className="md:col-span-2 space-y-4">
            <div>
              <h4 className="text-xs font-bold text-emerald-600 uppercase tracking-wider mb-2">Matched Keywords</h4>
              <div className="flex flex-wrap gap-2">
                {result.matchedKeywords.map((kw, i) => (
                  <span key={i} className="px-3 py-1 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full text-xs font-medium">{kw}</span>
                ))}
              </div>
            </div>
            <div>
              <h4 className="text-xs font-bold text-rose-600 uppercase tracking-wider mb-2">Missing Keywords</h4>
              <div className="flex flex-wrap gap-2">
                {result.missingKeywords.map((kw, i) => (
                  <span key={i} className="px-3 py-1 bg-rose-50 text-rose-700 border border-rose-200 rounded-full text-xs font-medium">{kw}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
